bool PcapNgFileReaderDevice::matchPacketWithFilter(const uint8_t* packetData, size_t packetLen, timespec packetTimestamp, uint16_t linkType)
{
        if (m_CurFilter == "")
                return true;

        int linkTypeAsInt = (int)linkType;

